 25	__device__ __forceinline__ float sigmoidf_stable(float x) {
 26	    if (x >= 0.0f) {
 27	        const float e = expf(-x);
 28	        return 1.0f / (1.0f + e);
 29	    }
 30	    const float e = expf(x);
 31	    return e / (1.0f + e);
 32	}
