 34	__device__ __forceinline__ float softplusf_stable(float x) {
 35	    if (x > 20.0f) {
 36	        return x;
 37	    }
 38	    if (x < -20.0f) {
 39	        return expf(x);
 40	    }
 41	    return log1pf(expf(x));
