 44	__global__ void gdr_decode_packed_bf16_kernel(
 45	    const bf16* __restrict__ mixed_qkv,
 46	    const bf16* __restrict__ a,
 47	    const bf16* __restrict__ b,
 48	    const bf16* __restrict__ dt_bias,
