 61	    const int64_t linear = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
 62	    const int64_t elems_per_row = 32 * 128;
 63	    const int64_t total = static_cast<int64_t>(batch) * elems_per_row;
