 80	    const int32_t qk_head = head / 4;
 81	    const bf16* row_qkv = mixed_qkv + static_cast<int64_t>(row) * qkv_row_stride;
 82	    const bf16* query = row_qkv + qk_head * 128;
 83	    const bf16* key = row_qkv + 1024 + qk_head * 128;
 84	    const bf16* value = row_qkv + 2048 + head * 128;
 85	
 86	    float q_sum = 0.0f;
 87	    float k_sum = 0.0f;
 88	    for (int32_t k_idx = 0; k_idx < 128; ++k_idx) {
 89	        const float q_raw = bf16_to_float(query[k_idx]);
 90	        const float k_raw = bf16_to_float(key[k_idx]);
 91	        q_sum += q_raw * q_raw;
 92	        k_sum += k_raw * k_raw;
 93	    }
